import { useEffect } from "react";
import { HouseSimple, MagnifyingGlass, Path, SignOut, UserCircle, Vault } from "@phosphor-icons/react";
import { Ghost } from "./components/Ghost.tsx";
import { applyLook, tab, useStore, type Screen } from "./lib/store.ts";
import { applyPrivacy, quickExit } from "./lib/privacy.ts";
import { useT, type Dict } from "./i18n/index.ts";
import { Onboarding } from "./screens/Onboarding.tsx";
import { Who } from "./screens/Who.tsx";
import { Home } from "./screens/Home.tsx";
import { Check } from "./screens/Check.tsx";
import { Result } from "./screens/Result.tsx";
import { Coach } from "./screens/Coach.tsx";
import { PathScreen } from "./screens/Path.tsx";
import { LessonPlayer } from "./screens/Lesson.tsx";
import { VaultScreen } from "./screens/Vault.tsx";
import { Me } from "./screens/Me.tsx";
import { AdultGuide } from "./screens/AdultGuide.tsx";
import { Teach, TeachLesson } from "./screens/Teach.tsx";
import { Mean } from "./screens/Mean.tsx";
import { StoryPlayer } from "./screens/Story.tsx";
import { Kit } from "./screens/Kit.tsx";
import { Counsel } from "./screens/Counsel.tsx";
import { Give } from "./screens/Give.tsx";
import { SafetyPlan } from "./screens/SafetyPlan.tsx";

const NAV: { screen: Screen; label: (t: Dict) => string; icon: typeof HouseSimple }[] = [
  { screen: { name: "home" }, label: (t) => t.nav.home, icon: HouseSimple },
  { screen: { name: "check" }, label: (t) => t.nav.check, icon: MagnifyingGlass },
  { screen: { name: "path" }, label: (t) => t.nav.path, icon: Path },
  { screen: { name: "vault" }, label: (t) => t.nav.vault, icon: Vault },
  { screen: { name: "me" }, label: (t) => t.nav.me, icon: UserCircle },
];

const TAB_OF: Record<Screen["name"], Screen["name"]> = {
  home: "home",
  check: "check",
  result: "check",
  coach: "check",
  path: "path",
  lesson: "path",
  vault: "vault",
  me: "me",
  adults: "me",
  teach: "me",
  teachLesson: "me",
  story: "path",
  kit: "me",
  counsel: "me",
  give: "me",
  mean: "home",
  plan: "vault",
};

/** Always in reach: one tap hides Ward and locks it (and on Android drops to the home screen). */
function QuickExit() {
  const t = useT();
  return (
    <button
      onClick={quickExit}
      title={t.common.quickExitHint}
      className="fixed end-3 top-3 z-30 inline-flex min-h-10 items-center gap-1.5 rounded-full border border-line bg-[color-mix(in_srgb,var(--bg),transparent_10%)] px-3 text-sm font-bold text-dim backdrop-blur-md hover:text-ink lg:top-4"
    >
      <SignOut size={16} weight="bold" className="flip-rtl" /> {t.common.quickExit}
    </button>
  );
}

export function App() {
  const profile = useStore((s) => s.profile);
  const locked = useStore((s) => s.locked);
  const hideRecents = useStore((s) => s.profiles.hideRecents);
  const screen = useStore((s) => s.screen);
  const t = useT();

  useEffect(() => applyLook(profile), [profile.look, profile.age, profile.lang]);
  useEffect(() => applyPrivacy(), [hideRecents]);

  if (locked) return <Who />;
  if (!profile.onboarded) return <Onboarding />;

  // Lessons take the whole screen, like Duolingo: no nav to tap away from by accident.
  if (screen.name === "lesson") return <LessonPlayer id={screen.id} />;
  if (screen.name === "story") return <StoryPlayer id={screen.id} />;
  // Class mode is projected: the whole screen is the lesson.
  if (screen.name === "teachLesson") return <TeachLesson id={screen.id} />;

  const current = TAB_OF[screen.name];
  return (
    <div className="lg:grid lg:grid-cols-[248px_1fr]">
      <QuickExit />
      <nav aria-label="Ward" className="sticky top-0 hidden h-[100dvh] flex-col border-e border-line px-4 py-6 lg:flex">
        <div className="mb-8 flex items-center gap-3 px-2">
          <Ghost size={34} glow={false} />
          <span className="font-display text-2xl font-bold tracking-tight">Ward</span>
        </div>
        <ul className="grid gap-1">
          {NAV.map(({ screen: s, label, icon: Icon }) => (
            <li key={s.name}>
              <button
                onClick={() => tab(s)}
                aria-current={current === s.name ? "page" : undefined}
                className={`flex w-full items-center gap-3 rounded-btn px-3 py-3 font-display text-[1.05rem] font-semibold transition-colors ${
                  current === s.name ? "bg-glow-soft text-glow" : "text-dim hover:bg-raised hover:text-ink"
                }`}
              >
                <Icon size={24} weight={current === s.name ? "fill" : "regular"} />
                {label(t)}
              </button>
            </li>
          ))}
        </ul>
        <p className="mt-auto px-2 text-xs leading-relaxed text-dim">{t.nav.runsHere}</p>
      </nav>

      <main className="min-h-[100dvh] pt-10 lg:pt-0">
        {screen.name === "home" && <Home />}
        {screen.name === "check" && <Check />}
        {screen.name === "result" && <Result id={screen.id} />}
        {screen.name === "coach" && <Coach id={screen.id} felt={screen.felt} />}
        {screen.name === "path" && <PathScreen />}
        {screen.name === "vault" && <VaultScreen />}
        {screen.name === "me" && <Me />}
        {screen.name === "adults" && <AdultGuide />}
        {screen.name === "teach" && <Teach />}
        {screen.name === "mean" && <Mean />}
        {screen.name === "kit" && <Kit />}
        {screen.name === "counsel" && <Counsel />}
        {screen.name === "give" && <Give />}
        {screen.name === "plan" && <SafetyPlan />}
      </main>

      <nav
        aria-label="Ward"
        className="fixed inset-x-0 bottom-0 z-20 border-t border-line bg-[color-mix(in_srgb,var(--bg),transparent_8%)] pb-[env(safe-area-inset-bottom)] backdrop-blur-xl lg:hidden"
      >
        <ul className="mx-auto grid max-w-lg grid-cols-5">
          {NAV.map(({ screen: s, label, icon: Icon }) => (
            <li key={s.name}>
              <button
                onClick={() => tab(s)}
                aria-current={current === s.name ? "page" : undefined}
                className={`flex h-16 w-full flex-col items-center justify-center gap-1 text-[0.72rem] font-bold ${current === s.name ? "text-glow" : "text-dim"}`}
              >
                <Icon size={24} weight={current === s.name ? "fill" : "regular"} />
                {label(t)}
              </button>
            </li>
          ))}
        </ul>
      </nav>
    </div>
  );
}

// App state. Each person on the device has a profile (name, look, streak, XP) in localStorage,
// so siblings on a shared phone each get their own Ward; a profile can be locked with a PIN.
// Chats are never stored here: an analysis stays in memory until the child chooses to save it,
// and then it goes into that profile's encrypted vault (vault.ts). The child's "this is wrong"
// corrections are kept here by message fingerprint only, never the words (corrections.ts).

import { useSyncExternalStore } from "react";
import type { Analysis, Chat, Level } from "@ward/engine";
import { withCorrection, type Correction } from "./corrections.ts";

export type LookId = "lantern" | "moonlit" | "firefly" | "ember" | "aurora" | "daylight";
export type AgeBand = "8" | "11" | "14";
export type Lang = "en" | "ur";

export type Screen =
  | { name: "home" }
  | { name: "check" }
  | { name: "result"; id: string }
  | { name: "coach"; id: string; felt?: boolean } // felt: from "It still feels wrong", so help comes first
  | { name: "path" }
  | { name: "lesson"; id: string }
  | { name: "vault" }
  | { name: "me" }
  | { name: "adults" }
  | { name: "teach" }
  | { name: "teachLesson"; id: string }
  | { name: "story"; id: string }
  | { name: "kit" }
  | { name: "counsel" }
  | { name: "give" }
  | { name: "mean" }
  | { name: "plan" };

export interface CheckSummary {
  id: string;
  at: number;
  title: string;
  level: Level;
  hostile: number;
  saved: boolean;
}

export interface Profile {
  onboarded: boolean;
  lang: Lang;
  name: string;
  age: AgeBand;
  look: LookId;
  xp: number;
  streak: number;
  lastLessonDay: string | null;
  done: string[];
  /** Story endings found, as "storyId:sceneId". */
  storyEnds: string[];
  checks: CheckSummary[];
  trusted: { name: string; how: string }[];
  ollamaUrl: string;
  model: string;
  /** Salt for the vault key. The PIN itself is never stored. */
  vaultSalt: string | null;
  /** An encrypted known value, to check a PIN without storing it. */
  vaultCheck: string | null;
  /** Show "Listen" buttons. Defaults on for the youngest band, set in onboarding's age step. */
  readAloud: boolean;
  /** "This is wrong": the child's corrections, by message fingerprint. */
  corrections: Record<string, Correction>;
  /** The helplines the child picked (a country id, or "OTHER"); null means guess from the time zone. */
  region: string | null;
}

/** The single-profile key from before shared-phone mode; migrated into the "default" profile. */
const LEGACY_KEY = "ward.profile.v1";
const INDEX_KEY = "ward.profiles.v1";
const profileKey = (id: string) => (id === "default" ? LEGACY_KEY : `ward.profile.${id}`);

/** What the "Who's using Ward?" screen needs, readable before a profile is unlocked. */
export interface ProfileEntry {
  id: string;
  name: string;
  look: LookId;
  /** PBKDF2 of the profile PIN; the PIN itself is never stored. */
  pinSalt?: string;
  pinHash?: string;
}

export interface ProfileIndex {
  list: ProfileEntry[];
  active: string;
  /** Hide Ward's screen in the recent-apps switcher (Android). On by default. */
  hideRecents: boolean;
}

const DEFAULTS: Profile = {
  onboarded: false,
  // Urdu by default on phones set to Urdu; everyone can switch on the first screen.
  lang: typeof navigator !== "undefined" && navigator.language?.startsWith("ur") ? "ur" : "en",
  name: "",
  age: "11",
  look: "lantern",
  xp: 0,
  streak: 0,
  lastLessonDay: null,
  done: [],
  storyEnds: [],
  checks: [],
  trusted: [],
  ollamaUrl: "http://127.0.0.1:11434",
  model: "gemma4:e4b",
  vaultSalt: null,
  vaultCheck: null,
  readAloud: false,
  corrections: {},
  region: null,
};

function read<T>(key: string): T | null {
  try {
    const raw = localStorage.getItem(key);
    return raw ? (JSON.parse(raw) as T) : null;
  } catch {
    return null;
  }
}

function write(key: string, value: unknown) {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch {
    // Private mode or storage full: Ward still works for this session.
  }
}

function loadIndex(): ProfileIndex {
  const idx = read<ProfileIndex>(INDEX_KEY);
  if (idx?.list?.length) return { ...idx, hideRecents: idx.hideRecents ?? true };
  // First run, or a device from before profiles: the existing data becomes "default".
  const legacy = read<Profile>(LEGACY_KEY);
  return { list: [{ id: "default", name: legacy?.name ?? "", look: legacy?.look ?? "lantern" }], active: "default", hideRecents: true };
}

function loadProfile(id: string): Profile {
  return { ...DEFAULTS, ...(read<Profile>(profileKey(id)) ?? {}) };
}

/** Work in progress: the open chat and its analysis, in memory only. */
export interface Session {
  chat: Chat;
  analysis: Analysis;
  title: string;
  self: string | null;
  /** Still running the model layer after the instant slang-pack result. */
  refining: boolean;
  progress?: [number, number];
  modelError?: string;
}

interface State {
  profile: Profile;
  profiles: ProfileIndex;
  /** True until the active profile's PIN is entered, or while choosing who is using Ward. */
  locked: boolean;
  screen: Screen;
  history: Screen[];
  sessions: Record<string, Session>;
  /** A chat shared into Ward from another app, waiting for the Check screen. */
  incoming: { files: File[]; text?: string; title?: string } | null;
}

const index0 = loadIndex();
const firstLocked = index0.list.length > 1 || !!index0.list.find((p) => p.id === index0.active)?.pinHash;
let state: State = {
  profile: loadProfile(index0.active),
  profiles: index0,
  locked: firstLocked,
  screen: { name: "home" },
  history: [],
  sessions: {},
  incoming: null,
};
const listeners = new Set<() => void>();

function emit() {
  for (const l of listeners) l();
}

export function setState(fn: (s: State) => State) {
  state = fn(state);
  const { profile, profiles } = state;
  write(profileKey(profiles.active), profile);
  // Keep the picker's name and look in step with the profile.
  const entry = profiles.list.find((p) => p.id === profiles.active);
  if (entry && (entry.name !== profile.name || entry.look !== profile.look)) {
    state = { ...state, profiles: { ...profiles, list: profiles.list.map((p) => (p.id === profiles.active ? { ...p, name: profile.name, look: profile.look } : p)) } };
  }
  write(INDEX_KEY, state.profiles);
  applyLook(state.locked ? { look: entry?.look ?? "lantern", age: "11", lang: profile.lang } : profile);
  emit();
}

export function useStore<T>(pick: (s: State) => T): T {
  return useSyncExternalStore(
    (cb) => {
      listeners.add(cb);
      return () => listeners.delete(cb);
    },
    () => pick(state),
  );
}

export const getState = () => state;

export function updateProfile(patch: Partial<Profile> | ((p: Profile) => Partial<Profile>)) {
  setState((s) => ({ ...s, profile: { ...s.profile, ...(typeof patch === "function" ? patch(s.profile) : patch) } }));
}

export function go(screen: Screen) {
  setState((s) => ({ ...s, history: [...s.history, s.screen].slice(-20), screen }));
  window.scrollTo({ top: 0 });
}

export function back(fallback: Screen = { name: "home" }) {
  setState((s) => {
    const prev = s.history.at(-1);
    return { ...s, screen: prev ?? fallback, history: s.history.slice(0, -1) };
  });
}

/** Top-level tabs reset history, so Back never walks across tabs. */
export function tab(screen: Screen) {
  setState((s) => ({ ...s, history: [], screen }));
  window.scrollTo({ top: 0 });
}

export function putSession(id: string, patch: Partial<Session> & Pick<Session, "chat" | "analysis" | "title" | "self">) {
  setState((s) => ({ ...s, sessions: { ...s.sessions, [id]: { refining: false, ...s.sessions[id], ...patch } } }));
}

export function patchSession(id: string, patch: Partial<Session>) {
  setState((s) => (s.sessions[id] ? { ...s, sessions: { ...s.sessions, [id]: { ...s.sessions[id]!, ...patch } } } : s));
}

export function applyLook(p: Pick<Profile, "look" | "age"> & Partial<Pick<Profile, "lang">>) {
  const root = document.documentElement;
  root.dataset.look = p.look;
  root.dataset.age = p.age;
  if (p.lang) {
    root.lang = p.lang;
    root.dir = p.lang === "ur" ? "rtl" : "ltr";
  }
  document.body.dataset.look = p.look;
  const meta = document.querySelector('meta[name="theme-color"]');
  if (meta) meta.setAttribute("content", getComputedStyle(root).getPropertyValue("--bg").trim() || "#0f1024");
}

export function today(d = new Date()) {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

/** Streak bookkeeping after a finished lesson: same day keeps it, the next day grows it. */
export function finishLesson(id: string, xp: number) {
  updateProfile((p) => {
    const t = today();
    const y = today(new Date(Date.now() - 86_400_000));
    const streak = p.lastLessonDay === t ? p.streak : p.lastLessonDay === y ? p.streak + 1 : 1;
    return { xp: p.xp + xp, streak, lastLessonDay: t, done: p.done.includes(id) ? p.done : [...p.done, id] };
  });
}

/** A story ending found. The first ending of each story earns XP and keeps the streak going. */
export function finishStory(storyId: string, endId: string, xp = 10) {
  const key = `${storyId}:${endId}`;
  updateProfile((p) => {
    if (p.storyEnds.includes(key)) return {};
    const first = !p.storyEnds.some((k) => k.startsWith(`${storyId}:`));
    const t = today();
    const y = today(new Date(Date.now() - 86_400_000));
    const streak = !first || p.lastLessonDay === t ? p.streak : p.lastLessonDay === y ? p.streak + 1 : 1;
    return { storyEnds: [...p.storyEnds, key], ...(first ? { xp: p.xp + xp, streak, lastLessonDay: t } : {}) };
  });
}

/** A streak only counts if the last lesson was today or yesterday. */
export function liveStreak(p: Profile) {
  const y = today(new Date(Date.now() - 86_400_000));
  return p.lastLessonDay === today() || p.lastLessonDay === y ? p.streak : 0;
}

/** Remember (or, with null, forget) the child's correction to one message. */
export function setCorrection(fp: string, c: Correction | null) {
  updateProfile((p) => ({ corrections: withCorrection(p.corrections, fp, c) }));
}

export const uid = () => Math.random().toString(36).slice(2, 10);

// ---- Shared phones -------------------------------------------------------------------------

const enc = new TextEncoder();
const b64 = (b: ArrayBuffer | Uint8Array) => btoa(String.fromCharCode(...new Uint8Array(b instanceof Uint8Array ? b : new Uint8Array(b))));

async function pinHash(pin: string, salt: string) {
  const base = await crypto.subtle.importKey("raw", enc.encode(pin), "PBKDF2", false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits({ name: "PBKDF2", salt: Uint8Array.from(atob(salt), (c) => c.charCodeAt(0)), iterations: 310_000, hash: "SHA-256" }, base, 256);
  return b64(bits);
}

/** Things to forget whenever the person using Ward changes: open chats, an unlocked vault. */
const onLeave = new Set<() => void>();
export function onProfileLeave(fn: () => void) {
  onLeave.add(fn);
}

function leave(s: State): State {
  for (const fn of onLeave) fn();
  return { ...s, sessions: {}, incoming: null, history: [], screen: { name: "home" } };
}

export function activeEntry(): ProfileEntry | undefined {
  return state.profiles.list.find((p) => p.id === state.profiles.active);
}

/** Open a profile. Returns false if it has a PIN and the PIN is wrong. */
export async function openProfile(id: string, pin?: string): Promise<boolean> {
  const entry = state.profiles.list.find((p) => p.id === id);
  if (!entry) return false;
  if (entry.pinHash && (!pin || (await pinHash(pin, entry.pinSalt!)) !== entry.pinHash)) return false;
  setState((s) => ({ ...leave(s), profiles: { ...s.profiles, active: id }, profile: loadProfile(id), locked: false }));
  return true;
}

export function addProfile() {
  const id = Math.random().toString(36).slice(2, 10);
  setState((s) => ({
    ...leave(s),
    profiles: { ...s.profiles, list: [...s.profiles.list, { id, name: "", look: "lantern" }], active: id },
    profile: { ...DEFAULTS, lang: s.profile.lang },
    locked: false,
  }));
}

export async function setProfilePin(pin: string | null) {
  const salt = pin ? b64(crypto.getRandomValues(new Uint8Array(16))) : undefined;
  const hash = pin ? await pinHash(pin, salt!) : undefined;
  setState((s) => ({ ...s, profiles: { ...s.profiles, list: s.profiles.list.map((p) => (p.id === s.profiles.active ? { ...p, pinSalt: salt, pinHash: hash } : p)) } }));
}

/** Delete a profile and its data from this device (its vault is removed by the caller). */
export function removeActiveProfile() {
  const id = state.profiles.active;
  try {
    localStorage.removeItem(profileKey(id));
  } catch {
    // nothing stored
  }
  const rest = state.profiles.list.filter((p) => p.id !== id);
  if (!rest.length) {
    try {
      localStorage.removeItem(INDEX_KEY);
    } catch {
      // nothing stored
    }
    location.reload();
    return;
  }
  setState((s) => ({ ...leave(s), profiles: { ...s.profiles, list: rest, active: rest[0]!.id }, profile: loadProfile(rest[0]!.id), locked: true }));
}

/** Who's using Ward? Also the quick exit's landing place. */
export function lockProfile() {
  setState((s) => ({ ...leave(s), locked: true }));
}

export function setHideRecents(on: boolean) {
  setState((s) => ({ ...s, profiles: { ...s.profiles, hideRecents: on } }));
}

export const vaultDbName = () => (state.profiles.active === "default" ? "ward-vault" : `ward-vault-${state.profiles.active}`);
// Shared-phone privacy: the quick exit, and keeping Ward out of Android's recent-apps screen.

import { Capacitor, registerPlugin } from "@capacitor/core";
import { getState, lockProfile } from "./store.ts";

const Privacy = registerPlugin<{ setSecure(o: { enabled: boolean }): Promise<void>; leave(): Promise<void> }>("Privacy");
const android = () => Capacitor.getPlatform() === "android";

export function applyPrivacy() {
  if (android()) void Privacy.setSecure({ enabled: getState().profiles.hideRecents }).catch(() => {});
}

/**
 * Quick exit: forget open chats, lock the vault, go back to "Who's using Ward?" (which asks for
 * a PIN if the profile has one), and on Android drop to the home screen.
 */
export function quickExit() {
  lockProfile();
  if (android()) void Privacy.leave().catch(() => {});
}

/** Desktop: pressing Escape twice quickly is the quick exit. */
export function listenForQuickExitKey() {
  let last = 0;
  window.addEventListener("keydown", (e) => {
    if (e.key !== "Escape") return;
    const now = Date.now();
    if (now - last < 600) quickExit();
    last = now;
  });
}

// The evidence vault. Saved chats are encrypted with AES-GCM under a key derived from the
// child's PIN (PBKDF2, 310k rounds) and kept in IndexedDB on this device. The PIN is never
// stored; a small encrypted marker lets Ward check it. Each saved message also gets a SHA-256
// fingerprint, so a printed report can show the evidence wasn't edited after saving.
// The sealing itself is in vaultSeal.ts.

import { fingerprintMessages, type Analysis, type Chat, type WardReport } from "@ward/engine";
import { getState, onProfileLeave, updateProfile, vaultDbName } from "./store.ts";
import { b64, derive, open, seal, unb64 } from "./vaultSeal.ts";

const STORE = "items";

export interface VaultItem {
  id: string;
  savedAt: number;
  title: string;
  self: string | null;
  chat: Chat;
  analysis: Analysis;
  /** sha256 of "sender|iso time|text" per message, in order. */
  fingerprints: string[];
  note?: string;
}

let key: CryptoKey | null = null;
// A vault never stays open when the person using Ward changes.
onProfileLeave(() => {
  key = null;
});

export const hasPin = () => Boolean(getState().profile.vaultSalt);
export const isUnlocked = () => key !== null;
export const lock = () => {
  key = null;
};

export async function createPin(pin: string) {
  const salt = crypto.getRandomValues(new Uint8Array(16));
  key = await derive(pin, salt);
  updateProfile({ vaultSalt: b64(salt), vaultCheck: await seal(key, "ward") });
}

export async function unlock(pin: string): Promise<boolean> {
  const { vaultSalt, vaultCheck } = getState().profile;
  if (!vaultSalt || !vaultCheck) return false;
  const k = await derive(pin, unb64(vaultSalt));
  try {
    if ((await open(k, vaultCheck)) !== "ward") return false;
    key = k;
    return true;
  } catch {
    return false;
  }
}

function db(): Promise<IDBDatabase> {
  return new Promise((res, rej) => {
    const r = indexedDB.open(vaultDbName(), 1);
    r.onupgradeneeded = () => r.result.createObjectStore(STORE, { keyPath: "id" });
    r.onsuccess = () => res(r.result);
    r.onerror = () => rej(r.error);
  });
}

function tx<T>(mode: IDBTransactionMode, fn: (s: IDBObjectStore) => IDBRequest<T>): Promise<T> {
  return db().then(
    (d) =>
      new Promise<T>((res, rej) => {
        const t = d.transaction(STORE, mode);
        // Close every connection when done, or a later wipe() is blocked and the data stays.
        t.oncomplete = t.onabort = t.onerror = () => d.close();
        const req = fn(t.objectStore(STORE));
        req.onsuccess = () => res(req.result);
        req.onerror = () => rej(req.error);
      }),
  );
}

export const fingerprint = (chat: Chat) => fingerprintMessages(chat);

/** Dates don't survive JSON; bring them back on the way out. */
function revive(item: VaultItem): VaultItem {
  const fix = (m: { at: string | Date | null }) => {
    m.at = m.at ? new Date(m.at) : null;
  };
  item.chat.messages.forEach(fix);
  item.chat.events.forEach(fix as never);
  item.analysis.findings.forEach((f) => fix(f.message));
  return item;
}

export async function save(item: Omit<VaultItem, "fingerprints" | "savedAt">) {
  if (!key) throw new Error("locked");
  const full: VaultItem = { ...item, savedAt: Date.now(), fingerprints: await fingerprint(item.chat) };
  const blob = await seal(key, JSON.stringify(full));
  await tx("readwrite", (s) => s.put({ id: item.id, blob }));
  updateProfile((p) => ({ checks: p.checks.map((c) => (c.id === item.id ? { ...c, saved: true } : c)) }));
}

export async function list(): Promise<VaultItem[]> {
  if (!key) throw new Error("locked");
  const rows = await tx<{ id: string; blob: string }[]>("readonly", (s) => s.getAll());
  const out: VaultItem[] = [];
  for (const r of rows) {
    if (r.id === PLAN_ID || r.id.startsWith(CASE_PREFIX)) continue;
    try {
      out.push(revive(JSON.parse(await open(key, r.blob))));
    } catch {
      // A row from an older PIN: skip rather than fail the whole list.
    }
  }
  return out.sort((a, b) => b.savedAt - a.savedAt);
}

export async function remove(id: string) {
  await tx("readwrite", (s) => s.delete(id));
  updateProfile((p) => ({ checks: p.checks.map((c) => (c.id === id ? { ...c, saved: false } : c)) }));
}

// The teen safety plan: one more sealed row in the same vault, under the same PIN.
export interface SafetyPlan {
  signs: string[];
  calm: string[];
  places: string[];
  people: string[];
  space: string[];
  updatedAt: number;
}
const PLAN_ID = "__plan";
export const emptyPlan = (): SafetyPlan => ({ signs: [], calm: [], places: [], people: [], space: [], updatedAt: 0 });

export async function savePlan(plan: SafetyPlan) {
  if (!key) throw new Error("locked");
  const blob = await seal(key, JSON.stringify({ ...plan, updatedAt: Date.now() }));
  await tx("readwrite", (s) => s.put({ id: PLAN_ID, blob }));
}

export async function loadPlan(): Promise<SafetyPlan> {
  if (!key) throw new Error("locked");
  const row = await tx<{ id: string; blob: string } | undefined>("readonly", (s) => s.get(PLAN_ID));
  if (!row) return emptyPlan();
  try {
    return { ...emptyPlan(), ...JSON.parse(await open(key, row.blob)) };
  } catch {
    return emptyPlan();
  }
}

// Counsellor mode: reports received from children, with the counsellor's own notes. Sealed in
// the same vault under the same PIN, one row per report, keyed by a hash of the whole report so
// the same report received twice is one case and an edited copy is a separate one.
export interface CaseNote {
  at: number;
  text: string;
}
export interface CaseRecord {
  id: string;
  receivedAt: number;
  via: "file" | "qr";
  report: WardReport;
  check: { digestOk: boolean; perMessage: boolean[] };
  status: "new" | "open" | "closed";
  notes: CaseNote[];
}
const CASE_PREFIX = "case:";

export async function saveCase(c: CaseRecord) {
  if (!key) throw new Error("locked");
  const blob = await seal(key, JSON.stringify(c));
  await tx("readwrite", (s) => s.put({ id: CASE_PREFIX + c.id, blob }));
}

export async function listCases(): Promise<CaseRecord[]> {
  if (!key) throw new Error("locked");
  const rows = await tx<{ id: string; blob: string }[]>("readonly", (s) => s.getAll());
  const out: CaseRecord[] = [];
  for (const r of rows) {
    if (!r.id.startsWith(CASE_PREFIX)) continue;
    try {
      out.push(JSON.parse(await open(key, r.blob)));
    } catch {
      // sealed under an older PIN
    }
  }
  return out.sort((a, b) => b.receivedAt - a.receivedAt);
}

export async function removeCase(id: string) {
  await tx("readwrite", (s) => s.delete(CASE_PREFIX + id));
}

/** Wipes the vault and the PIN. For "forgot my PIN" and "delete everything". */
export async function wipe() {
  key = null;
  await new Promise<void>((res) => {
    const r = indexedDB.deleteDatabase(vaultDbName());
    r.onsuccess = r.onerror = r.onblocked = () => res();
  });
  updateProfile((p) => ({ vaultSalt: null, vaultCheck: null, checks: p.checks.map((c) => ({ ...c, saved: false })) }));
}
// The vault's sealing, kept apart from IndexedDB and the store so it can be tested on its own.
// A sealed value is "<iv base64>.<ciphertext base64>": AES-GCM under a key from the PIN.
// Every row saved so far uses this format, so changing it would lock children out of evidence
// they already saved. Only the encoder changed: it now builds the string in chunks, because
// spreading a whole long chat into String.fromCharCode throws past about 120 KB.

const enc = new TextEncoder();
const dec = new TextDecoder();

/** Same output as btoa(String.fromCharCode(...bytes)), for any size. */
export const b64 = (b: ArrayBuffer | Uint8Array) => {
  const bytes = b instanceof Uint8Array ? b : new Uint8Array(b);
  let s = "";
  for (let i = 0; i < bytes.length; i += 0x8000) s += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return btoa(s);
};

export const unb64 = (s: string): Uint8Array<ArrayBuffer> => {
  const bin = atob(s);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
};

export async function derive(pin: string, salt: Uint8Array<ArrayBuffer>) {
  const base = await crypto.subtle.importKey("raw", enc.encode(pin), "PBKDF2", false, ["deriveKey"]);
  return crypto.subtle.deriveKey({ name: "PBKDF2", salt, iterations: 310_000, hash: "SHA-256" }, base, { name: "AES-GCM", length: 256 }, false, ["encrypt", "decrypt"]);
}

export async function seal(k: CryptoKey, data: string) {
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ct = await crypto.subtle.encrypt({ name: "AES-GCM", iv }, k, enc.encode(data));
  return `${b64(iv)}.${b64(ct)}`;
}

export async function open(k: CryptoKey, sealed: string) {
  const [iv, ct] = sealed.split(".");
  const pt = await crypto.subtle.decrypt({ name: "AES-GCM", iv: unb64(iv!) }, k, unb64(ct!));
  return dec.decode(pt);
}
import { useEffect, useRef, useState } from "react";
import { motion, useAnimationControls } from "motion/react";
import { Backspace } from "@phosphor-icons/react";
import { useT } from "../i18n/index.ts";

/** Four big digits and a keypad that works with touch and a keyboard alike. */
export function PinPad({ title, hint, onDone }: { title: string; hint?: string; onDone: (pin: string) => Promise<boolean | void> | boolean | void }) {
  const t = useT();
  const [pin, setPin] = useState("");
  const [busy, setBusy] = useState(false);
  const controls = useAnimationControls();
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => ref.current?.focus(), []);

  async function press(d: string) {
    if (busy) return;
    const next = (pin + d).slice(0, 4);
    setPin(next);
    if (next.length === 4) {
      setBusy(true);
      let ok: boolean | void;
      try {
        ok = await onDone(next);
      } catch (e) {
        setPin("");
        throw e;
      } finally {
        // Whatever onDone does, the pad never stays frozen with four dots in it.
        setBusy(false);
      }
      if (ok === false) {
        await controls.start({ x: [0, -10, 10, -6, 6, 0], transition: { duration: 0.35 } });
        setPin("");
      }
    }
  }

  return (
    <div
      ref={ref}
      tabIndex={-1}
      onKeyDown={(e) => {
        if (/^\d$/.test(e.key)) press(e.key);
        if (e.key === "Backspace") setPin((p) => p.slice(0, -1));
      }}
      dir="ltr" className="mx-auto flex max-w-xs flex-col items-center outline-none"
    >
      <h2 dir="auto" className="text-center font-display text-2xl font-bold tracking-tight">{title}</h2>
      {hint && <p dir="auto" className="mt-2 text-center text-dim">{hint}</p>}
      <motion.div animate={controls} className="my-7 flex gap-4" aria-live="polite" aria-label={t.vault.pinDigits(pin.length)}>
        {[0, 1, 2, 3].map((i) => (
          <span key={i} className={`size-4 rounded-full transition-colors ${i < pin.length ? "bg-glow" : "bg-raised"}`} />
        ))}
      </motion.div>
      <div className="grid w-full grid-cols-3 gap-3">
        {["1", "2", "3", "4", "5", "6", "7", "8", "9", "", "0", "del"].map((k) =>
          k === "" ? (
            <span key="blank" />
          ) : (
            <button
              key={k}
              onClick={() => (k === "del" ? setPin((p) => p.slice(0, -1)) : press(k))}
              aria-label={k === "del" ? t.vault.del1 : k}
              className="grid h-16 place-items-center rounded-btn bg-raised font-display text-2xl font-semibold active:scale-95"
            >
              {k === "del" ? <Backspace size={24} /> : k}
            </button>
          ),
        )}
      </div>
    </div>
  );
}
// "Save to vault" with the PIN steps inline: create one the first time, unlock after that.
// If saving fails (storage full or blocked), the child is told calmly and can try again.

import { useState } from "react";
import { AnimatePresence, motion } from "motion/react";
import { ArrowClockwise, CheckCircle, LockKey, X } from "@phosphor-icons/react";
import { Button } from "./ui.tsx";
import { PinPad } from "./PinPad.tsx";
import { createPin, hasPin, isUnlocked, save, unlock } from "../lib/vault.ts";
import { useStore } from "../lib/store.ts";
import { useT } from "../i18n/index.ts";

export function SaveToVault({ id }: { id: string }) {
  const t = useT();
  const s = useStore((st) => st.sessions[id]);
  const saved = useStore((st) => st.profile.checks.find((c) => c.id === id)?.saved ?? false);
  const [step, setStep] = useState<null | "create" | "confirm" | "unlock" | "failed">(null);
  const [first, setFirst] = useState("");

  /** Runs one vault step; a throw shows the calm "didn't save" panel instead of failing silently. */
  async function attempt(fn: () => Promise<boolean | void>) {
    try {
      return await fn();
    } catch {
      setStep("failed");
    }
  }

  async function saveNow() {
    if (!s) return;
    await save({ id, title: s.title, self: s.self, chat: s.chat, analysis: s.analysis });
    setStep(null);
  }

  function start() {
    if (!hasPin()) setStep("create");
    else if (!isUnlocked()) setStep("unlock");
    else void attempt(saveNow);
  }

  if (saved)
    return (
      <Button tone="quiet" disabled>
        <CheckCircle size={20} weight="fill" className="text-safe" /> {t.vault.saved}
      </Button>
    );

  return (
    <>
      <Button tone="quiet" onClick={start}>
        <LockKey size={20} weight="bold" /> {t.vault.save}
      </Button>
      <AnimatePresence>
        {step && (
          <motion.div
            role="dialog"
            aria-modal
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-40 grid place-items-center bg-[color-mix(in_srgb,var(--bg),transparent_15%)] p-4 backdrop-blur-md"
          >
            <motion.div initial={{ y: 24 }} animate={{ y: 0 }} className="relative w-full max-w-sm rounded-card border border-line bg-surface p-6 pt-10">
              <button onClick={() => setStep(null)} className="absolute end-3 top-3 grid size-11 place-items-center rounded-full text-dim hover:bg-raised" aria-label={t.common.close}>
                <X size={20} weight="bold" />
              </button>
              {step === "create" && (
                <PinPad
                  title={t.vault.makePin}
                  hint={t.vault.makePinHint}
                  onDone={(p) => {
                    setFirst(p);
                    setStep("confirm");
                  }}
                />
              )}
              {step === "confirm" && (
                <PinPad
                  key="confirm"
                  title={t.vault.again}
                  hint={t.vault.againHint}
                  onDone={async (p) => {
                    if (p !== first) {
                      setStep("create");
                      return false;
                    }
                    await attempt(async () => {
                      await createPin(p);
                      await saveNow();
                    });
                  }}
                />
              )}
              {step === "unlock" && (
                <PinPad
                  title={t.vault.unlock}
                  onDone={(p) =>
                    attempt(async () => {
                      if (!(await unlock(p))) return false;
                      await saveNow();
                    })
                  }
                />
              )}
              {step === "failed" && (
                <div className="flex flex-col items-center gap-5 text-center">
                  <p role="alert" dir="auto" className="text-lg">{t.vault.saveFailed}</p>
                  <Button onClick={start}>
                    <ArrowClockwise size={20} weight="bold" /> {t.vault.tryAgain}
                  </Button>
                </div>
              )}
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}

