function SideDoor({ icon: I, text: [title, line], onClick, expanded, controls }: { icon: Icon; text: [string, string]; onClick: () => void; expanded?: boolean; controls?: string }) {
  return (
    <button onClick={onClick} aria-expanded={expanded} aria-controls={expanded ? controls : undefined} className="group flex items-center gap-4 rounded-card border border-line bg-surface px-5 py-4 text-start hover:border-dim/40">
      <I size={24} weight="bold" className="shrink-0 text-glow" />
      <span className="min-w-0 flex-1">
        <span className="block font-display font-semibold">{title}</span>
        <span className="text-sm text-dim">{line}</span>
      </span>
      {expanded === undefined ? (
        <ArrowRight size={18} weight="bold" className="flip-rtl shrink-0 text-glow transition-transform group-hover:translate-x-0.5" />
      ) : (
        <CaretDown size={18} weight="bold" className={`shrink-0 text-glow transition-transform ${expanded ? "rotate-180" : ""}`} />
      )}
    </button>
  );
}
// "Make a report": the child chooses who it's for, what about themselves to include, and what
// they want to happen. Everything about them is optional. If they say they're in danger now,
// the helplines come first.

import { useState } from "react";
import { motion } from "motion/react";
import { FilePdf, QrCode, X } from "@phosphor-icons/react";
import { buildReport, WANTS, type Want, type WardReport } from "@ward/engine";
import { Button } from "./ui.tsx";
import { HelpNow } from "./HelpNow.tsx";
import { QrSend } from "./QrSend.tsx";
import { exportReport } from "../lib/report.ts";
import { useStore } from "../lib/store.ts";
import { useT } from "../i18n/index.ts";
import type { VaultItem } from "../lib/vault.ts";

const RECIPIENTS = [
  { id: "helpline", label: "A helpline" },
  { id: "school", label: "My school" },
  { id: "adult", label: "A trusted adult" },
  { id: "police", label: "The police" },
] as const;

export function ReportDialog({ item, onClose }: { item: VaultItem; onClose: () => void }) {
  const p = useStore((s) => s.profile);
  const t = useT();
  const [recipient, setRecipient] = useState<(typeof RECIPIENTS)[number]["id"]>("helpline");
  const [firstName, setFirstName] = useState(p.name);
  const [city, setCity] = useState("");
  const [shareAge, setShareAge] = useState(true);
  const [wants, setWants] = useState<Want[]>(["stop"]);
  const [danger, setDanger] = useState<boolean | null>(null);
  const [busy, setBusy] = useState(false);
  const [made, setMade] = useState<WardReport | null>(null);
  const [qr, setQr] = useState(false);

  const field = "mt-1.5 w-full rounded-btn border border-line bg-bg px-4 py-3 text-ink placeholder:text-dim/70 focus:border-glow focus:outline-none";

  return (
    <motion.div role="dialog" aria-modal aria-labelledby="report-title" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="fixed inset-0 z-40 overflow-y-auto bg-[color-mix(in_srgb,var(--bg),transparent_10%)] p-4 backdrop-blur-md">
      <motion.div initial={{ y: 20 }} animate={{ y: 0 }} className="relative mx-auto my-8 w-full max-w-xl rounded-card border border-line bg-surface p-6">
        <button onClick={onClose} className="absolute end-3 top-3 grid size-11 place-items-center rounded-full text-dim hover:bg-raised" aria-label={t.common.close}>
          <X size={20} weight="bold" />
        </button>
        <h2 id="report-title" className="font-display text-2xl font-bold tracking-tight">
          {t.report.title}
        </h2>
        <p className="mt-1 text-dim">{t.report.line}</p>

        <fieldset className="mt-6">
          <legend className="text-sm font-bold text-dim">{t.report.forWho}</legend>
          <div className="mt-2 grid grid-cols-2 gap-2">
            {RECIPIENTS.map((r) => (
              <button key={r.id} onClick={() => setRecipient(r.id)} aria-pressed={recipient === r.id} className={`min-h-11 rounded-btn text-sm font-bold ${recipient === r.id ? "bg-glow text-glow-ink" : "bg-raised text-dim hover:text-ink"}`}>
                {t.report.recipients[r.id]}
              </button>
            ))}
          </div>
        </fieldset>

        <fieldset className="mt-6">
          <legend className="text-sm font-bold text-dim">{t.report.danger}</legend>
          <div className="mt-2 grid grid-cols-2 gap-2">
            {[
              [true, t.report.yes],
              [false, t.report.no],
            ].map(([v, l]) => (
              <button key={String(v)} onClick={() => setDanger(v as boolean)} aria-pressed={danger === v} className={`min-h-11 rounded-btn text-sm font-bold ${danger === v ? (v ? "bg-alarm text-[#1c0505]" : "bg-glow text-glow-ink") : "bg-raised text-dim hover:text-ink"}`}>
                {l as string}
              </button>
            ))}
          </div>
          {danger && (
            <div className="mt-4">
              <HelpNow />
            </div>
          )}
        </fieldset>

        <fieldset className="mt-6">
          <legend className="text-sm font-bold text-dim">{t.report.wants}</legend>
          <div className="mt-2 grid gap-2">
            {(Object.keys(WANTS) as Want[]).map((w) => (
              <label key={w} className="flex min-h-11 cursor-pointer items-center gap-3 rounded-btn bg-raised px-4">
                <input type="checkbox" className="size-5 accent-[var(--glow)]" checked={wants.includes(w)} onChange={(e) => setWants((x) => (e.target.checked ? [...x, w] : x.filter((y) => y !== w)))} />
                {t.report.wantLabels[w]}
              </label>
            ))}
          </div>
        </fieldset>

        <fieldset className="mt-6">
          <legend className="text-sm font-bold text-dim">{t.report.about}</legend>
          <label htmlFor="r-name" className="mt-2 block text-sm text-dim">
            {t.report.firstName}
          </label>
          <input id="r-name" value={firstName} onChange={(e) => setFirstName(e.target.value)} className={field} />
          <label htmlFor="r-city" className="mt-3 block text-sm text-dim">
            {t.report.city}
          </label>
          <input id="r-city" value={city} onChange={(e) => setCity(e.target.value)} placeholder={t.report.cityPlaceholder} className={field} />
          <label className="mt-3 flex min-h-11 cursor-pointer items-center gap-3">
            <input type="checkbox" className="size-5 accent-[var(--glow)]" checked={shareAge} onChange={(e) => setShareAge(e.target.checked)} />
            {t.report.includeAge}
          </label>
        </fieldset>

        <Button
          className="mt-8 w-full"
          disabled={busy}
          onClick={async () => {
            setBusy(true);
            const r = await buildReport({
              chat: item.chat,
              analysis: item.analysis,
              fingerprints: item.fingerprints,
              savedAt: new Date(item.savedAt),
              title: item.title,
              platform: item.chat.source === "whatsapp" ? "WhatsApp" : "a messaging app",
              reporter: { firstName, city, ageBand: shareAge ? p.age : undefined },
              inDangerNow: danger,
              wants,
              recipient,
            });
            setMade(r);
            setBusy(false);
          }}
        >
          <FilePdf size={20} weight="bold" /> {busy ? t.report.making : t.report.make}
        </Button>
        <p className="mt-2 text-sm text-dim">{t.report.note}</p>
        {made && (
          <div role="dialog" aria-modal aria-labelledby="made-title" className="absolute inset-0 overflow-y-auto rounded-card bg-surface p-6 pt-12">
            <button onClick={() => (qr ? setQr(false) : setMade(null))} className="absolute end-3 top-3 grid size-11 place-items-center rounded-full text-dim hover:bg-raised" aria-label={t.common.close}>
              <X size={20} weight="bold" />
            </button>
            {qr ? (
              <QrSend json={JSON.stringify(made)} />
            ) : (
              <>
                <h2 id="made-title" className="font-display text-2xl font-bold tracking-tight">{t.counsel.made}</h2>
                <p className="mt-2 text-dim">{t.counsel.madeLine}</p>
                <div className="mt-6 grid gap-3">
                  <Button onClick={() => exportReport(made)}>
                    <FilePdf size={20} weight="bold" /> {t.counsel.saveFiles}
                  </Button>
                  <Button tone="quiet" onClick={() => setQr(true)}>
                    <QrCode size={20} weight="bold" /> {t.counsel.qrGive}
                  </Button>
                </div>
              </>
            )}
          </div>
        )}
      </motion.div>
    </motion.div>
  );
}
// "Keep my corrections": the child's corrections for this chat as a small file they can keep,
// and give to their teacher if their school joins a Ward pilot. The dialog shows the file itself,
// exactly as it will be saved. Children never get the words of the messages in it: the "include
// the words" box is only for a future counsellor flow (`allowText`), and nothing passes it yet.
// Names and times never go in. Nothing is sent.

import { useState } from "react";
import { motion } from "motion/react";
import { DownloadSimple, X } from "@phosphor-icons/react";
import { Button } from "./ui.tsx";
import { correctionsFile, type Correction } from "../lib/corrections.ts";
import { useStore } from "../lib/store.ts";
import { useT } from "../i18n/index.ts";

async function saveFile(json: string) {
  const file = new File([json], "ward-corrections.json", { type: "application/json" });
  if (navigator.canShare?.({ files: [file] })) {
    try {
      await navigator.share({ files: [file], title: "Ward corrections" });
      return;
    } catch {
      // cancelled: fall through to a download
    }
  }
  const a = document.createElement("a");
  a.href = URL.createObjectURL(file);
  a.download = file.name;
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 5000);
}

export function ShareCorrections({
  items,
  wordLists,
  onClose,
  allowText = false,
}: {
  items: { correction: Correction; text: string }[];
  wordLists: string[];
  onClose: () => void;
  /** Counsellor flow only (not built yet). Children never see the "include the words" box. */
  allowText?: boolean;
}) {
  const t = useT();
  const lang = useStore((s) => s.profile.lang);
  const [ticked, setIncludeText] = useState(false);
  const includeText = allowText && ticked;
  const json = JSON.stringify(correctionsFile(items, { includeText, language: lang, wordLists }), null, 2);

  return (
    <motion.div role="dialog" aria-modal aria-labelledby="share-corrections" initial={{ opacity: 0 }} animate={{ opacity: 1 }} className="fixed inset-0 z-40 overflow-y-auto bg-[color-mix(in_srgb,var(--bg),transparent_10%)] p-4 backdrop-blur-md">
      <motion.div initial={{ y: 20 }} animate={{ y: 0 }} className="relative mx-auto my-8 w-full max-w-xl rounded-card border border-line bg-surface p-6">
        <button onClick={onClose} className="absolute end-3 top-3 grid size-11 place-items-center rounded-full text-dim hover:bg-raised" aria-label={t.common.close}>
          <X size={20} weight="bold" />
        </button>
        <h2 id="share-corrections" className="pe-10 font-display text-2xl font-bold tracking-tight">
          {t.correct.shareTitle}
        </h2>
        <p className="mt-2 text-dim">{t.correct.shareLine}</p>

        {allowText && (
          <label className="mt-6 flex min-h-11 cursor-pointer items-start gap-3 rounded-btn bg-raised px-4 py-3">
            <input type="checkbox" className="mt-0.5 size-5 shrink-0 accent-[var(--glow)]" checked={includeText} onChange={(e) => setIncludeText(e.target.checked)} />
            <span>
              <span className="block font-semibold">{t.correct.includeText}</span>
              <span className="text-sm text-dim">{t.correct.includeTextHint}</span>
            </span>
          </label>
        )}

        <h3 className="mt-6 text-sm font-bold text-dim">{t.correct.preview}</h3>
        <pre dir="ltr" className="mt-2 max-h-72 overflow-auto rounded-btn border border-line bg-bg p-3 text-start font-mono text-xs leading-relaxed whitespace-pre-wrap break-words">
          {json}
        </pre>

        <Button className="mt-6 w-full" onClick={() => void saveFile(json)}>
          <DownloadSimple size={20} weight="bold" /> {t.correct.save}
        </Button>
        <p className="mt-3 text-sm text-dim">{t.correct.where}</p>
      </motion.div>
    </motion.div>
  );
}
// The handful of building blocks every screen uses. One radius system (card and button radii
// from the age band), one accent (the look's glow), Phosphor icons at one weight.

import type { ButtonHTMLAttributes, ReactNode } from "react";
import { ArrowLeft } from "@phosphor-icons/react";
import { back } from "../lib/store.ts";
import { useT } from "../i18n/index.ts";

type Tone = "glow" | "quiet" | "alarm" | "ghost";

export function Button({ tone = "glow", className = "", children, ...rest }: ButtonHTMLAttributes<HTMLButtonElement> & { tone?: Tone }) {
  const tones: Record<Tone, string> = {
    glow: "bg-glow text-glow-ink shadow-[0_8px_30px_-10px_var(--halo)] hover:brightness-105",
    quiet: "bg-raised text-ink hover:bg-[color-mix(in_srgb,var(--raised),var(--ink)_6%)]",
    alarm: "bg-alarm text-[#1c0505] hover:brightness-105",
    ghost: "text-ink hover:bg-raised",
  };
  return (
    <button
      className={`inline-flex min-h-12 items-center justify-center gap-2 whitespace-nowrap rounded-btn px-5 font-display text-[1.02rem] font-semibold tracking-tight transition-[transform,filter,background-color] duration-150 active:scale-[0.98] disabled:pointer-events-none disabled:opacity-40 ${tones[tone]} ${className}`}
      {...rest}
    >
      {children}
    </button>
  );
}

export function Card({ children, className = "", as: As = "section" }: { children: ReactNode; className?: string; as?: "section" | "div" | "article" }) {
  return <As className={`rounded-card border border-line bg-surface ${className}`}>{children}</As>;
}

export function BackBar({ title, right }: { title?: string; right?: ReactNode }) {
  const t = useT();
  return (
    <div className="mb-4 flex min-h-12 items-center gap-2">
      <button onClick={() => back()} className="-ms-2 grid size-11 place-items-center rounded-full text-dim hover:bg-raised hover:text-ink" aria-label="Back">
        <ArrowLeft size={22} weight="bold" className="flip-rtl" />
      </button>
      {title && <h1 className="font-display text-lg font-semibold tracking-tight">{title}</h1>}
      <div className="ms-auto">{right}</div>
    </div>
  );
}

export function Pill({ children, tone = "quiet" }: { children: ReactNode; tone?: "quiet" | "glow" | "alarm" | "safe" }) {
  const t = {
    quiet: "bg-raised text-dim",
    glow: "bg-glow-soft text-glow",
    alarm: "bg-alarm-soft text-alarm",
    safe: "bg-[color-mix(in_srgb,var(--safe),transparent_86%)] text-safe",
  }[tone];
  return <span className={`inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[0.8rem] font-bold ${t}`}>{children}</span>;
}

export function Screen({ children, wide = false }: { children: ReactNode; wide?: boolean }) {
  return <div className={`mx-auto w-full px-4 pb-32 pt-4 sm:px-6 lg:pb-16 lg:pt-8 ${wide ? "max-w-5xl" : "max-w-2xl"}`}>{children}</div>;
}

