/*
  Ward's looks. Every look is a night with one light in it: a dark room and a single warm
  accent ("glow"). The child picks one in onboarding and can switch any time in Settings.
  data-age sets how playful the shapes and type feel: 8 (8 to 10), 11 (11 to 13), 14 (14 to 17).
  Semantic colours (alarm, safe) stay the same in every look so danger always reads as danger.
*/

@theme {
  --font-display: "Bricolage Grotesque Variable", ui-sans-serif, system-ui, sans-serif;
  --font-sans: "Atkinson Hyperlegible Next", ui-sans-serif, system-ui, sans-serif;

