  --color-dim: var(--dim);
  --color-glow: var(--glow);
  --color-glow-ink: var(--glow-ink);
  --color-glow-soft: var(--glow-soft);
  --color-alarm: var(--alarm);
  --color-alarm-soft: var(--alarm-soft);
  --color-safe: var(--safe);

  --radius-card: var(--r-card);
  --radius-btn: var(--r-btn);
}

