/* The room's light: one soft pool of the look's glow, fixed behind everything. */
body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(60rem 40rem at 85% -10%, var(--glow-soft), transparent 60%),
    radial-gradient(40rem 30rem at -10% 110%, rgb(120 110 255 / 0.06), transparent 60%);
  z-index: 0;
}
[data-look="daylight"] body::before,
body[data-look="daylight"]::before {
  opacity: 0.6;
}

#root {
  position: relative;
  z-index: 1;
}

:focus-visible {
  outline: 3px solid var(--glow);
  outline-offset: 3px;
}

.font-display {
  font-variation-settings: "opsz" 48;
}

/* Ward's float, blink and the rim trail used by the drop zone. */
@keyframes ward-float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-6px);
  }
}
@keyframes ward-blink {
  0%,
  92%,
  100% {
    transform: scaleY(1);
  }
  95% {
    transform: scaleY(0.1);
  }
}
@keyframes rim-trail {
  to {
    offset-distance: 100%;
  }
}
@keyframes rim-drift {
  0%,
  100% {
    transform: translateX(-30%);
  }
  50% {
    transform: translateX(30%);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* Urdu: Nastaliq, the script children read in school books. It sits taller than Latin type,
   so lines get more room, and the display face falls back to it too. Latin names, numbers and
   chat messages inside Urdu screens still use the Latin faces. */
html[lang="ur"] body {
  font-family: "Noto Nastaliq Urdu", var(--font-sans);
  line-height: 2.1;
}
html[lang="ur"] .font-display {
  font-family: "Noto Nastaliq Urdu", var(--font-display);
  letter-spacing: 0;
  line-height: 1.9;
}
html[lang="ur"] h1,
html[lang="ur"] h2,
html[lang="ur"] h3 {
  line-height: 1.9;
}
/* Nastaliq's tall stacked letters need room; outrank Tailwind's leading-* utilities. */
html[lang="ur"] p,
html[lang="ur"] li,
html[lang="ur"] dd,
html[lang="ur"] dt,
html[lang="ur"] label,
html[lang="ur"] button {
  line-height: 2.05;
}
/* Chat messages, names and numbers keep Latin metrics even inside an Urdu screen. */
html[lang="ur"] [dir="ltr"],
html[lang="ur"] [lang="en"] {
  line-height: 1.5;
}
/* Arrows point the way the reader reads. */
[dir="rtl"] .flip-rtl {
  transform: scaleX(-1);
}
